20	function parseArgs(argv) {
21	  const args = {};
22	  for (let index = 0; index < argv.length; index += 2) {
23	    const key = argv[index];
24	    const value = argv[index + 1];
25	    if (!key?.startsWith('--') || value === undefined) {
26	      usage(`Invalid argument near ${key ?? '<end>'}`);
27	    }
28	    args[key.slice(2)] = value;
29	  }
30	  return args;
31	}
