40	function resolveRef(document, schema, seen = new Set()) {
41	  if (!schema?.$ref) {
42	    return schema;
43	  }
44	  if (!schema.$ref.startsWith('#/')) {
45	    usage(`Only local OpenAPI refs are supported: ${schema.$ref}`);
46	  }
47	  if (seen.has(schema.$ref)) {
48	    usage(`Circular OpenAPI ref detected: ${schema.$ref}`);
49	  }
50	  const activeRefs = new Set(seen);
51	  activeRefs.add(schema.$ref);
52	  const parts = schema.$ref
53	    .replace(/^#\//, '')
54	    .split('/')
55	    .map((part) => part.replaceAll('~1', '/').replaceAll('~0', '~'));
56	  let current = document;
57	  for (const part of parts) {
58	    const currentRecord = asRecord(current, schema.$ref);
59	    if (!(part in currentRecord)) {
60	      usage(`OpenAPI ref not found: ${schema.$ref}`);
61	    }
62	    current = currentRecord[part];
63	  }
64	  return resolveRef(document, current, activeRefs);
65	}
