67	function getJsonMediaEntry(document, content) {
68	  const contentRecord = asRecord(content || {}, 'content');
69	  const exactJson = contentRecord['application/json'];
70	  const entry = exactJson
71	    ? ['application/json', exactJson]
72	    : Object.entries(contentRecord).find(([mediaType]) => isJsonMediaType(mediaType));
73	  return entry
74	    ? { mediaType: entry[0], media: asRecord(resolveRef(document, entry[1]), entry[0]) }
75	    : undefined;
76	}
