108	function isJsonMediaType(mediaType) {
109	  const normalized = mediaType.split(';', 1)[0].trim().toLowerCase();
110	  return (
111	    normalized === 'application/json' ||
112	    normalized.endsWith('/json') ||
113	    normalized.endsWith('+json')
114	  );
115	}
