121	function isMultipartMediaType(mediaType) {
122	  return mediaType.split(';', 1)[0].trim().toLowerCase() === 'multipart/form-data';
123	}
124	
125	function isTextMediaType(mediaType) {
126	  return mediaType.split(';', 1)[0].trim().toLowerCase().startsWith('text/');
