133	function findOperation(document, operationId) {
134	  const paths = asRecord(document.paths, 'paths');
135	  for (const [pathTemplate, pathItem] of Object.entries(paths)) {
136	    const pathItemRecord = asRecord(pathItem, pathTemplate);
137	    for (const [method, operation] of Object.entries(pathItemRecord)) {
