143	          pathTemplate,
144	          pathItem: pathItemRecord,
145	          method: method.toUpperCase(),
146	          operation: asRecord(operation, operationId),
147	        };
148	      }
149	    }
150	  }
151	  usage(`Operation not found: ${operationId}`);
